package com.aivle.backend.journey;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface JourneyMarketingAssetVersionRepository extends JpaRepository<JourneyMarketingAssetVersion,Long>{@EntityGraph(attributePaths={"asset","asset.workspace","conceptVersion"})@Query("select v from JourneyMarketingAssetVersion v where v.asset.workspace.id=:workspaceId and v.deletedAt is null order by v.asset.assetType,v.asset.displayOrder,v.versionNumber desc")List<JourneyMarketingAssetVersion> findCurrentByWorkspace(@Param("workspaceId")Long workspaceId);@EntityGraph(attributePaths={"asset","asset.workspace","conceptVersion"})Optional<JourneyMarketingAssetVersion> findTopByAssetIdAndDeletedAtIsNullOrderByVersionNumberDesc(Long assetId);}
